def comps(blk,color):
    seen=set(); best=0
    for r in range(5):
        for c in range(5):
            if blk[r][c]==color and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); n=0
                while st:
                    a,b=st.pop(); n+=1
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<5 and 0<=y<5 and blk[x][y]==color and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                best=max(best,n)
    return best
